CREATE TABLE IF NOT EXISTS event_revision(entity_type VARCHAR(64) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,version BIGINT NOT NULL,PRIMARY KEY(entity_type,aggregate_id));
CREATE TABLE IF NOT EXISTS domain_outbox(event_id VARCHAR(36) NOT NULL,destination VARCHAR(32) NOT NULL,url VARCHAR(500) NOT NULL,payload LONGTEXT NOT NULL,status VARCHAR(16) NOT NULL,attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(100),next_attempt DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),delivered_at DATETIME(6),PRIMARY KEY(event_id,destination),KEY idx_outbox_due(status,next_attempt));
CREATE TABLE IF NOT EXISTS domain_inbox(event_id VARCHAR(36) PRIMARY KEY,source VARCHAR(32) NOT NULL,payload_hash CHAR(64) NOT NULL,received_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS projection_revision(entity_type VARCHAR(100) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,version BIGINT NOT NULL,PRIMARY KEY(entity_type,aggregate_id));
CREATE TABLE IF NOT EXISTS domain_workflow(operation_id VARCHAR(36) PRIMARY KEY,request_key VARCHAR(250) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,action VARCHAR(32) NOT NULL,order_id BIGINT NOT NULL,status VARCHAR(16) NOT NULL,completion_json LONGTEXT,result_json LONGTEXT,attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(100),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY idx_workflow_pending(status,created_at));
CREATE TABLE IF NOT EXISTS order_workflow(operation_id VARCHAR(36) PRIMARY KEY,domain_name VARCHAR(32) NOT NULL,action VARCHAR(32) NOT NULL,order_id BIGINT NOT NULL,request_hash VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY idx_order_workflow(order_id,status));
CREATE TABLE IF NOT EXISTS marketing_tcc_journal(operation_id VARCHAR(36) PRIMARY KEY,order_id BIGINT,decision VARCHAR(16) NOT NULL,payload LONGTEXT NOT NULL,done TINYINT NOT NULL DEFAULT 0,attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(100),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY idx_marketing_journal(done,created_at));
CREATE TABLE IF NOT EXISTS marketing_reservation(operation_id VARCHAR(36) PRIMARY KEY,order_id BIGINT,customer_id BIGINT NOT NULL,deal_id BIGINT,coupon_id BIGINT,room_count INT NOT NULL,state VARCHAR(16) NOT NULL,released TINYINT NOT NULL DEFAULT 0,request_json LONGTEXT NOT NULL,quote_json LONGTEXT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY idx_marketing_deal(deal_id,state,released));
CREATE TABLE IF NOT EXISTS stay_charge(operation_id VARCHAR(36) PRIMARY KEY,order_id BIGINT NOT NULL,payment_no VARCHAR(64) NOT NULL,amount DECIMAL(12,2) NOT NULL,paid_time DATETIME(6) NOT NULL);
